import React from 'react';
import { useStaticQuery, graphql } from 'gatsby';
import Img from 'gatsby-image';

const AboutImg = ({ filename, alt }) => {
  const data = useStaticQuery(graphql`
    query {
      images: allFile(filter: { relativePath: { ne: "" } }) {
        edges {
          node {
            relativePath
            childImageSharp {
              fixed(width: 350, quality: 100) {
                ...GatsbyImageSharpFixed
              }
            }
          }
        }
      }
    }
  `);

  const image = data.images.edges.find(
    (edge) => edge.node.relativePath === filename,
  );

  if (!image) return <span>Picture not found</span>;

  return <Img alt={alt || 'Profile'} fixed={image.node.childImageSharp.fixed} />;
};

export default AboutImg;
